const webhookData = $('Webhook').first().json;
const container = ((webhookData.query && webhookData.query.container) || '').trim().toUpperCase();

if (!container) {
  return [{ json: { error: 'container parameter required' } }];
}

const trackerResp = $('Fetch Tracker Sheet').first().json;
const fcMappingResp = $('Fetch FC Mapping').first().json;
const slaDaysResp = $('Fetch SLA Days').first().json;

function getFirstValues(resp) {
  if (resp.valueRanges && resp.valueRanges[0]) return resp.valueRanges[0].values || [];
  return resp.values || [];
}

function parseSheet(resp) {
  const values = getFirstValues(resp);
  if (values.length < 2) return [];
  const headers = values[0].map(h => (h || '').trim().toLowerCase());
  return values.slice(1).map(row => {
    const obj = {};
    headers.forEach((h, i) => { obj[h] = (row[i] !== undefined ? String(row[i]) : '').trim(); });
    return obj;
  });
}

function parseFCMapping(resp) {
  const values = getFirstValues(resp);
  const fcMapping = {};
  if (values.length < 2) return fcMapping;
  const headers = values[0].map(h => (h || '').trim().toLowerCase());
  const fcIdx = headers.findIndex(h => h === 'fc');
  const regIdx = headers.findIndex(h => h === 'region');
  const typeIdx = headers.findIndex(h => h === 'type');
  for (let i = 1; i < values.length; i++) {
    const row = values[i];
    const fc = (row[fcIdx] || '').trim().toUpperCase();
    const region = (row[regIdx] || '').trim();
    const type = (row[typeIdx] || '').trim();
    if (fc && region && type) fcMapping[fc] = { region, type };
  }
  return fcMapping;
}

function parseSLADays(resp) {
  const values = getFirstValues(resp);
  const slaTable = {};
  if (values.length < 2) return slaTable;
  const headers = values[0].map(h => (h || '').trim().toLowerCase());
  const tlIdx = headers.findIndex(h => h.includes('trade lane') || h === 'trade lane');
  const regIdx = headers.findIndex(h => h === 'region' || h === 'fc region');
  const typeIdx = headers.findIndex(h => h === 'type');
  const slaIdx = headers.findIndex(h => h.includes('sla') || h.includes('total'));
  for (let i = 1; i < values.length; i++) {
    const row = values[i];
    const tradeLane = normalizeTradeLane((row[tlIdx] || '').trim());
    const region = (row[regIdx] || '').trim();
    const type = (row[typeIdx] || '').trim();
    const sla = parseInt(row[slaIdx]);
    if (tradeLane && region && type && !isNaN(sla)) {
      slaTable[`${tradeLane}|${region}|${type}`] = sla;
    }
  }
  return slaTable;
}

function normalizeTradeLane(raw) {
  if (!raw) return null;
  const s = raw.trim();
  if (/^[A-Z]{2}2[A-Z]{2}$/i.test(s)) return s.toUpperCase();
  const m = s.match(/^([A-Za-z]{2})\s+to\s+([A-Za-z]{2})$/i);
  if (m) return `${m[1].toUpperCase()}2${m[2].toUpperCase()}`;
  return s.toUpperCase().replace(/\s/g, '');
}

function parseDate(str) {
  if (!str || !str.trim()) return null;
  const s = str.trim();
  if (/^\d{4}-\d{2}-\d{2}/.test(s)) return new Date(s.slice(0,10) + 'T00:00:00Z');
  const dmy = s.match(/^(\d{1,2})-([A-Za-z]{3})-(\d{2,4})$/);
  if (dmy) {
    const MONTHS = {jan:0,feb:1,mar:2,apr:3,may:4,jun:5,jul:6,aug:7,sep:8,oct:9,nov:10,dec:11};
    const mon = MONTHS[dmy[2].toLowerCase()];
    let yr = parseInt(dmy[3]);
    if (yr < 100) yr += 2000;
    if (mon !== undefined) return new Date(Date.UTC(yr, mon, parseInt(dmy[1])));
  }
  const d = new Date(s);
  return isNaN(d.getTime()) ? null : d;
}

function daysBetween(a, b) { return Math.round((a - b) / 86400000); }
function addDays(d, n) { const r = new Date(d); r.setUTCDate(r.getUTCDate() + Math.round(n)); return r; }
function fmtDate(d) { return d ? d.toISOString().slice(0,10) : null; }

const rawRows = parseSheet(trackerResp);
const fcMapping = parseFCMapping(fcMappingResp);
const slaTable = parseSLADays(slaDaysResp);
const today = new Date();
today.setUTCHours(0,0,0,0);

const filtered = rawRows.filter(r => (r['qid'] || '').startsWith('XQAMZ'));

const processed = filtered.map(row => {
  const qid = row['qid'] || '';
  const cont = (row['container #'] || '').trim().toUpperCase();
  const customer = row['customer'] || '';
  const destination = row['destination'] || '';
  const flippedfccode = (row['flippedfccode'] || '').trim().toUpperCase();
  const tradeLane = normalizeTradeLane(row['origin country / trade lane'] || '');
  const arrivalETA = parseDate(row['arrival eta']);
  const daysInExecution = parseFloat(row['days in execution']) || 0;
  const status = (row['status'] || '').trim();

  let committedSLA = parseFloat(row['commited sla days']) || null;
  if (flippedfccode && tradeLane) {
    const fcInfo = fcMapping[flippedfccode];
    if (fcInfo) {
      const key = `${tradeLane}|${fcInfo.region}|${fcInfo.type}`;
      if (slaTable[key] !== undefined) committedSLA = slaTable[key];
    }
  }

  let estimatedExecDays = null;
  if (arrivalETA !== null) {
    estimatedExecDays = daysInExecution + daysBetween(arrivalETA, today);
  }

  let targetLmTat = null;
  if (committedSLA !== null) {
    const breached = daysInExecution >= committedSLA;
    const delivered = status === 'Delivered to Consignee';
    if (breached && delivered) targetLmTat = 'n/a, breached & delivered';
    else if (breached && !delivered) targetLmTat = 'n/a, will breach upon delivery';
    else if (!breached && delivered) targetLmTat = 'n/a, delivered within SLA';
    else targetLmTat = estimatedExecDays !== null ? committedSLA - estimatedExecDays : null;
  }
  if (typeof targetLmTat === 'number' && targetLmTat < 0) targetLmTat = 'n/a, will breach upon delivery';
  if (typeof targetLmTat === 'number') targetLmTat = Math.min(targetLmTat, 7);

  let final = null;
  if (targetLmTat === 'n/a, breached & delivered') final = 'Delivered outside SLA';
  else if (targetLmTat === 'n/a, will breach upon delivery') final = 'Will breach SLA upon delivery';
  else if (targetLmTat === 'n/a, delivered within SLA') final = 'Delivered within SLA';
  else if (typeof targetLmTat === 'number') final = targetLmTat;

  return { qid, container: cont, customer, destination, arrivalETA, daysInExecution, committedSLA, status, estimatedExecDays, targetLmTat, final };
});

const byContainer = {};
for (const row of processed) {
  if (!row.container) continue;
  if (!byContainer[row.container]) byContainer[row.container] = [];
  byContainer[row.container].push(row);
}

const qids = byContainer[container];
if (!qids || qids.length === 0) {
  return [{ json: { error: `Container "${container}" not found in the current dataset.` } }];
}

const arrivalETA = qids[0].arrivalETA;
const numericTats = qids.map(q => q.targetLmTat).filter(t => typeof t === 'number');

let suggestedDate = null;
let suggestedText = null;

if (numericTats.length > 0) {
  const minTat = Math.min(...numericTats);
  suggestedDate = fmtDate(addDays(arrivalETA, minTat));
} else {
  const priority = ['n/a, will breach upon delivery', 'n/a, breached & delivered', 'n/a, delivered within SLA'];
  const texts = qids.map(q => q.targetLmTat).filter(Boolean);
  suggestedText = priority.find(p => texts.includes(p)) || texts[0] || null;
}

return [{
  json: {
    container,
    suggestedDate,
    suggestedText,
    arrivalETA: fmtDate(arrivalETA),
    qids: qids.map(q => ({
      qid: q.qid,
      customer: q.customer,
      destination: q.destination,
      status: q.status,
      daysInExecution: q.daysInExecution,
      committedSLA: q.committedSLA,
      estimatedExecDays: q.estimatedExecDays !== null ? Math.round(q.estimatedExecDays) : null,
      targetLmTat: typeof q.targetLmTat === 'number' ? Math.round(q.targetLmTat) : q.targetLmTat,
      final: typeof q.final === 'number' ? Math.round(q.final) : q.final,
    })),
  }
}];
